CREATE OR REPLACE FUNCTION mwd_finance_private.post_demo_transfer_ledger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_tx uuid; v_source uuid; v_destination uuid;
begin
 if new.kind <> 'transfer' then return new; end if;
 if new.amount_cents is null or new.amount_cents<=0 or new.source_user_id is null or new.destination_user_id is null or new.source_user_id=new.destination_user_id then
 raise exception 'Transferencia demo invalida para contabilidad' using errcode='23514';
 end if;
 insert into mwd_finance_private.ledger_accounts(account_code,owner_user_id,currency_code,account_type)
 values ('MWD-DEMO-USER-'||new.source_user_id::text,new.source_user_id,'MWD','customer_liability')
 on conflict(account_code) do nothing;
 insert into mwd_finance_private.ledger_accounts(account_code,owner_user_id,currency_code,account_type)
 values ('MWD-DEMO-USER-'||new.destination_user_id::text,new.destination_user_id,'MWD','customer_liability')
 on conflict(account_code) do nothing;
 select id into v_source from mwd_finance_private.ledger_accounts where account_code='MWD-DEMO-USER-'||new.source_user_id::text and owner_user_id=new.source_user_id and currency_code='MWD' for update;
 select id into v_destination from mwd_finance_private.ledger_accounts where account_code='MWD-DEMO-USER-'||new.destination_user_id::text and owner_user_id=new.destination_user_id and currency_code='MWD' for update;
 if v_source is null or v_destination is null then raise exception 'Cuenta contable demo no valida'; end if;
 insert into mwd_finance_private.ledger_transactions(external_reference,transaction_kind,currency_code,status)
 values ('mwd-demo-transfer:'||new.id::text,'wallet_transfer','MWD','draft') returning id into v_tx;
 insert into mwd_finance_private.ledger_entries(transaction_id,account_id,entry_side,amount_minor)
 values (v_tx,v_source,'debit',new.amount_cents),(v_tx,v_destination,'credit',new.amount_cents);
 update mwd_finance_private.ledger_transactions set status='posted' where id=v_tx;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mwd_owner_accounting_alerts_demo()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_wallet_issues bigint; v_ledger_issues bigint; v_wallet_ok bigint; v_ledger_ok bigint;
begin
 perform mwd_partners_private.assert_owner();
 select count(*) filter(where alert_status<>'ok'),count(*) filter(where alert_status='ok')
 into v_wallet_issues,v_wallet_ok from mwd_finance_private.demo_wallet_alerts_v1;
 select count(*) filter(where alert_status<>'ok'),count(*) filter(where alert_status='ok')
 into v_ledger_issues,v_ledger_ok from mwd_finance_private.demo_ledger_alerts_v1;
 return jsonb_build_object('mode','sandbox_only','realPaymentsEnabled',false,
 'walletsChecked',v_wallet_ok+v_wallet_issues,'walletAlerts',v_wallet_issues,
 'transfersChecked',v_ledger_ok+v_ledger_issues,'ledgerAlerts',v_ledger_issues,
 'status',case when v_wallet_issues+v_ledger_issues=0 then 'ok' else 'review_required' end);
end $function$
